static esp_err_t i2c_master_init(void)
{
    i2c_config_t conf = {
        .mode = I2C_MODE_MASTER,
        .sda_io_num = I2C_MASTER_SDA_IO,
        .scl_io_num = I2C_MASTER_SCL_IO,
        .sda_pullup_en = GPIO_PULLUP_ENABLE,
        .scl_pullup_en = GPIO_PULLUP_ENABLE,
        .master.clk_speed = I2C_MASTER_FREQ_HZ,
    };
    esp_err_t err = i2c_param_config(I2C_MASTER_NUM, &conf);
    if (err != ESP_OK) return err;
    return i2c_driver_install(I2C_MASTER_NUM, conf.mode, 0, 0, 0);
}

static esp_err_t max30102_read_fifo(uint32_t *red, uint32_t *ir)
{
    uint8_t buf[6];
    esp_err_t err = max30102_read_reg(MAX30102_REG_FIFO_DATA, buf, 6);
    if (err != ESP_OK) return err;

    *red = ((uint32_t)(buf[0] & 0x3F) << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir  = ((uint32_t)(buf[3] & 0x3F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];

    return ESP_OK;
}

static esp_err_t max30102_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t data[2] = {reg, value};
    return i2c_master_write_to_device(I2C_MASTER_NUM, MAX30102_I2C_ADDRESS,
                                       data, sizeof(data),
                                       pdMS_TO_TICKS(I2C_MASTER_TIMEOUT_MS));
}

static esp_err_t max30102_read_reg(uint8_t reg, uint8_t *data, size_t len)
{
    return i2c_master_write_read_device(I2C_MASTER_NUM, MAX30102_I2C_ADDRESS,
                                         &reg, 1, data, len,
                                         pdMS_TO_TICKS(I2C_MASTER_TIMEOUT_MS));
}

static esp_err_t max30102_init(void)
{
    esp_err_t err;

    err = max30102_write_reg(MAX30102_REG_MODE_CONFIG, 0x40);
    if (err != ESP_OK) return err;
    vTaskDelay(pdMS_TO_TICKS(100));

    err = max30102_write_reg(MAX30102_REG_INTR_ENABLE_1, 0xC0);
    if (err != ESP_OK) return err;

    err = max30102_write_reg(MAX30102_REG_FIFO_WR_PTR, 0x00);
    if (err != ESP_OK) return err;
    err = max30102_write_reg(MAX30102_REG_OVF_COUNTER, 0x00);
    if (err != ESP_OK) return err;
    err = max30102_write_reg(MAX30102_REG_FIFO_RD_PTR, 0x00);
    if (err != ESP_OK) return err;

    err = max30102_write_reg(MAX30102_REG_MODE_CONFIG, 0x03);
    if (err != ESP_OK) return err;

    err = max30102_write_reg(MAX30102_REG_SPO2_CONFIG, 0x27);
    if (err != ESP_OK) return err;

    err = max30102_write_reg(MAX30102_REG_LED1_PA, 0xFF);
    if (err != ESP_OK) return err;
    err = max30102_write_reg(MAX30102_REG_LED2_PA, 0xFF);
    if (err != ESP_OK) return err;

    ESP_LOGI(TAG, "MAX30102 initialized");
    return ESP_OK;
}

static ssd1306_handle_t oled_init(void)
{
    ssd1306_handle_t oled = ssd1306_create(I2C_MASTER_NUM, OLED_I2C_ADDRESS);
    if (oled == NULL) return NULL;
    ssd1306_refresh_gram(oled);
    ssd1306_clear_screen(oled, 0x00);
    return oled;
}

static void display_raw(ssd1306_handle_t oled, uint32_t bpm, uint32_t ir)
{
    char line[32];
    ssd1306_clear_screen(oled, 0x00);

    snprintf(line, sizeof(line), "BPM: %lu", bpm);
    ssd1306_draw_string(oled, 0, 0, (const uint8_t *)line, 16, 1);

    snprintf(line, sizeof(line), "IR:  %lu", ir);
    ssd1306_draw_string(oled, 0, 16, (const uint8_t *)line, 16, 1);

    if (bpm == 0) {
        snprintf(line, sizeof(line), "Place finger");
        ssd1306_draw_string(oled, 0, 32, (const uint8_t *)line, 16, 1);
        snprintf(line, sizeof(line), "on sensor...");
        ssd1306_draw_string(oled, 0, 48, (const uint8_t *)line, 16, 1);
    } else {
        snprintf(line, sizeof(line), "Reading OK");
        ssd1306_draw_string(oled, 0, 32, (const uint8_t *)line, 16, 1);
    }

    ssd1306_refresh_gram(oled);
}

static int calculate_bpm(uint32_t *ir_buffer, int buffer_size)
{
    uint32_t avg = 0;
    for (int i = 0; i < buffer_size; i++) {
        avg += ir_buffer[i];
    }
    avg /= buffer_size;

    if (avg < FINGER_THRESHOLD) return 0;

    uint32_t min_val = ir_buffer[0], max_val = ir_buffer[0];
    for (int i = 1; i < buffer_size; i++) {
        if (ir_buffer[i] < min_val) min_val = ir_buffer[i];
        if (ir_buffer[i] > max_val) max_val = ir_buffer[i];
    }
    uint32_t range = max_val - min_val;

    if (range < 200) return 0;

    uint32_t peak_threshold = avg + (range * 3 / 10);

    int last_peak_index = -1;
    int peak_intervals[20];
    int interval_count = 0;

    for (int i = 1; i < buffer_size - 1; i++) {
        if (ir_buffer[i] > ir_buffer[i-1] &&
            ir_buffer[i] > ir_buffer[i+1] &&
            ir_buffer[i] > peak_threshold) {

            if (last_peak_index != -1) {
                int interval = i - last_peak_index;
                if (interval >= 7 && interval <= 31 && interval_count < 20) {
                    peak_intervals[interval_count++] = interval;
                }
            }
            last_peak_index = i;
        }
    }

    if (interval_count < 2) return 0;

    int avg_interval = 0;
    for (int i = 0; i < interval_count; i++) {
        avg_interval += peak_intervals[i];
    }
    avg_interval /= interval_count;

    int clean_interval = 0;
    int clean_count = 0;
    for (int i = 0; i < interval_count; i++) {
        int diff = peak_intervals[i] - avg_interval;
        if (diff < 0) diff = -diff;
        if (diff < avg_interval / 5) {
            clean_interval += peak_intervals[i];
            clean_count++;
        }
    }

    if (clean_count < 2) return 0;
    clean_interval /= clean_count;

    int bpm = 60000 / (clean_interval * SAMPLE_RATE_MS);

    if (bpm < 40 || bpm > 200) return 0;

    return bpm;
}

void app_main(void)
{
    esp_err_t err = i2c_master_init();
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "I2C init failed");
        return;
    }

    ssd1306_handle_t oled = oled_init();
    if (oled == NULL) {
        ESP_LOGE(TAG, "OLED init failed");
        return;
    }

    err = max30102_init();
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "MAX30102 init failed");
        return;
    }

    uint32_t red = 0, ir = 0;
    uint32_t ir_buffer[SAMPLE_BUFFER_SIZE];
    int buffer_index = 0;
    int bpm = 0;

    int bpm_history[5] = {0};
    int bpm_history_index = 0;

    while (1) {
        uint8_t wr_ptr = 0, rd_ptr = 0;
        max30102_read_reg(MAX30102_REG_FIFO_WR_PTR, &wr_ptr, 1);
        max30102_read_reg(MAX30102_REG_FIFO_RD_PTR, &rd_ptr, 1);
        int num_samples = (wr_ptr - rd_ptr + 32) % 32;

        // DEBUG — always print pointer values
        ESP_LOGI(TAG, "WR: %d  RD: %d  samples: %d", wr_ptr, rd_ptr, num_samples);

        for (int s = 0; s < num_samples; s++) {
            err = max30102_read_fifo(&red, &ir);
            if (err != ESP_OK) break;

            ESP_LOGI(TAG, "RAW IR: %lu  RED: %lu", ir, red);

            if (ir > FINGER_THRESHOLD) {
                ir_buffer[buffer_index++] = ir;

                if (buffer_index >= SAMPLE_BUFFER_SIZE) {
                    buffer_index = 0;
                    bpm = calculate_bpm(ir_buffer, SAMPLE_BUFFER_SIZE);

                    if (bpm > 0) {
                        bpm_history[bpm_history_index++ % 5] = bpm;
                        int bpm_avg = 0;
                        int count = 0;
                        for (int i = 0; i < 5; i++) {
                            if (bpm_history[i] > 0) {
                                bpm_avg += bpm_history[i];
                                count++;
                            }
                        }
                        bpm_avg = count > 0 ? bpm_avg / count : 0;
                        ESP_LOGI(TAG, "BPM: %d (avg: %d)", bpm, bpm_avg);
                        display_raw(oled, bpm_avg, ir);
                    } else {
                        display_raw(oled, 0, ir);
                    }
                }
            } else {
                buffer_index = 0;
                display_raw(oled, 0, 0);
                ESP_LOGI(TAG, "No finger");
            }
        }

        vTaskDelay(pdMS_TO_TICKS(SAMPLE_RATE_MS));
    }
}

static inline esp_err_t ssd1306_write_cmd_byte(ssd1306_handle_t dev, const uint8_t cmd)
{
    return ssd1306_write_cmd(dev, &cmd, 1);
}

static esp_err_t ssd1306_write_data(ssd1306_handle_t dev, const uint8_t *const data, const uint16_t data_len)
{
    ssd1306_dev_t *device = (ssd1306_dev_t *) dev;
    esp_err_t ret;

    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
    ret = i2c_master_start(cmd);
    assert(ESP_OK == ret);
    ret = i2c_master_write_byte(cmd, device->dev_addr | I2C_MASTER_WRITE, true);
    assert(ESP_OK == ret);
    ret = i2c_master_write_byte(cmd, SSD1306_WRITE_DAT, true);
    assert(ESP_OK == ret);
    ret = i2c_master_write(cmd, data, data_len, true);
    assert(ESP_OK == ret);
    ret = i2c_master_stop(cmd);
    assert(ESP_OK == ret);
    ret = i2c_master_cmd_begin(device->bus, cmd, 1000 / portTICK_PERIOD_MS);
    i2c_cmd_link_delete(cmd);

    return ret;
}

void ssd1306_draw_num(ssd1306_handle_t dev, uint8_t chXpos, uint8_t chYpos,
                      uint32_t chNum, uint8_t chLen, uint8_t chSize)
{
    uint8_t i;
    uint8_t chTemp, chShow = 0;

    for (i = 0; i < chLen; i++) {
        chTemp = (chNum / _pow(10, chLen - i - 1)) % 10;
        if (chShow == 0 && i < (chLen - 1)) {
            if (chTemp == 0) {
                ssd1306_draw_char(dev, chXpos + (chSize / 2) * i, chYpos,
                                  ' ', chSize, 1);
                continue;
            } else {
                chShow = 1;
            }
        }
        ssd1306_draw_char(dev, chXpos + (chSize / 2) * i, chYpos,
                          chTemp + '0', chSize, 1);
    }
}

void ssd1306_draw_string(ssd1306_handle_t dev, uint8_t chXpos, uint8_t chYpos,
                         const uint8_t *pchString, uint8_t chSize, uint8_t chMode)
{
    while (*pchString != '\0') {
        if (chXpos > (SSD1306_WIDTH - chSize / 2)) {
            chXpos = 0;
            chYpos += chSize;
            if (chYpos > (SSD1306_HEIGHT - chSize)) {
                chYpos = chXpos = 0;
                ssd1306_clear_screen(dev, 0x00);
            }
        }
        ssd1306_draw_char(dev, chXpos, chYpos, *pchString, chSize, chMode);
        chXpos += chSize / 2;
        pchString++;
    }
}

void ssd1306_draw_1616char(ssd1306_handle_t dev, uint8_t chXpos, uint8_t chYpos, uint8_t chChar)
{
    uint8_t i, j;
    uint8_t chTemp = 0, chYpos0 = chYpos, chMode = 0;

    for (i = 0; i < 32; i++) {
        chTemp = c_chFont1612[chChar - 0x30][i];
        for (j = 0; j < 8; j++) {
            chMode = chTemp & 0x80 ? 1 : 0;
            ssd1306_fill_point(dev, chXpos, chYpos, chMode);
            chTemp <<= 1;
            chYpos++;
            if ((chYpos - chYpos0) == 16) {
                chYpos = chYpos0;
                chXpos++;
                break;
            }
        }
    }
}

void ssd1306_draw_bitmap(ssd1306_handle_t dev, uint8_t chXpos, uint8_t chYpos,
                         const uint8_t *pchBmp, uint8_t chWidth, uint8_t chHeight)
{
    uint16_t i, j, byteWidth = (chWidth + 7) / 8;

    for (j = 0; j < chHeight; j++) {
        for (i = 0; i < chWidth; i++) {
            if (*(pchBmp + j * byteWidth + i / 8) & (128 >> (i & 7))) {
                ssd1306_fill_point(dev, chXpos + i, chYpos + j, 1);
            }
        }
    }
}

void ssd1306_delete(ssd1306_handle_t dev)
{
    ssd1306_dev_t *device = (ssd1306_dev_t *) dev;
    free(device);
}

static uint32_t _pow(uint8_t m, uint8_t n)
{
    uint32_t result = 1;
    while (n--) {
        result *= m;
    }
    return result;
}

static esp_err_t ssd1306_write_cmd(ssd1306_handle_t dev, const uint8_t *const data, const uint16_t data_len)
{
    ssd1306_dev_t *device = (ssd1306_dev_t *) dev;
    esp_err_t ret;

    i2c_cmd_handle_t cmd = i2c_cmd_link_create();
    ret = i2c_master_start(cmd);
    assert(ESP_OK == ret);
    ret = i2c_master_write_byte(cmd, device->dev_addr | I2C_MASTER_WRITE, true);
    assert(ESP_OK == ret);
    ret = i2c_master_write_byte(cmd, SSD1306_WRITE_CMD, true);
    assert(ESP_OK == ret);
    ret = i2c_master_write(cmd, data, data_len, true);
    assert(ESP_OK == ret);
    ret = i2c_master_stop(cmd);
    assert(ESP_OK == ret);
    ret = i2c_master_cmd_begin(device->bus, cmd, 1000 / portTICK_PERIOD_MS);
    i2c_cmd_link_delete(cmd);

    return ret;
}

void ssd1306_fill_rectangle(ssd1306_handle_t dev, uint8_t chXpos1,
                            uint8_t chYpos1, uint8_t chXpos2, uint8_t chYpos2, uint8_t chDot)
{
    uint8_t chXpos, chYpos;

    for (chXpos = chXpos1; chXpos <= chXpos2; chXpos++) {
        for (chYpos = chYpos1; chYpos <= chYpos2; chYpos++) {
            ssd1306_fill_point(dev, chXpos, chYpos, chDot);
        }
    }
}

void ssd1306_draw_char(ssd1306_handle_t dev, uint8_t chXpos, uint8_t chYpos,
                       uint8_t chChr, uint8_t chSize, uint8_t chMode)
{
    uint8_t i, j;
    uint8_t chTemp, chYpos0 = chYpos;

    chChr = chChr - ' ';
    for (i = 0; i < chSize; i++) {
        if (chSize == 12) {
            if (chMode) {
                chTemp = c_chFont1206[chChr][i];
            } else {
                chTemp = ~c_chFont1206[chChr][i];
            }
        } else {
            if (chMode) {
                chTemp = c_chFont1608[chChr][i];
            } else {
                chTemp = ~c_chFont1608[chChr][i];
            }
        }

        for (j = 0; j < 8; j++) {
            if (chTemp & 0x80) {
                ssd1306_fill_point(dev, chXpos, chYpos, 1);
            } else {
                ssd1306_fill_point(dev, chXpos, chYpos, 0);
            }
            chTemp <<= 1;
            chYpos++;

            if ((chYpos - chYpos0) == chSize) {
                chYpos = chYpos0;
                chXpos++;
                break;
            }
        }
    }
}

void ssd1306_fill_point(ssd1306_handle_t dev, uint8_t chXpos, uint8_t chYpos, uint8_t chPoint)
{
    ssd1306_dev_t *device = (ssd1306_dev_t *) dev;
    uint8_t chPos, chBx, chTemp = 0;

    if (chXpos > 127 || chYpos > 63) {
        return;
    }
    chPos = 7 - chYpos / 8;
    chBx = chYpos % 8;
    chTemp = 1 << (7 - chBx);

    if (chPoint) {
        device->s_chDisplayBuffer[chXpos][chPos] |= chTemp;
    } else {
        device->s_chDisplayBuffer[chXpos][chPos] &= ~chTemp;
    }
}

void ssd1306_draw_3216char(ssd1306_handle_t dev, uint8_t chXpos, uint8_t chYpos, uint8_t chChar)
{
    uint8_t i, j;
    uint8_t chTemp = 0, chYpos0 = chYpos, chMode = 0;

    for (i = 0; i < 64; i++) {
        chTemp = c_chFont3216[chChar - 0x30][i];
        for (j = 0; j < 8; j++) {
            chMode = chTemp & 0x80 ? 1 : 0;
            ssd1306_fill_point(dev, chXpos, chYpos, chMode);
            chTemp <<= 1;
            chYpos++;
            if ((chYpos - chYpos0) == 32) {
                chYpos = chYpos0;
                chXpos++;
                break;
            }
        }
    }
}

void ssd1306_draw_line(ssd1306_handle_t dev, int16_t chXpos1, int16_t chYpos1, int16_t chXpos2, int16_t chYpos2)
{
    // 16-bit variables allowing a display overflow effect
    int16_t x_len = abs(chXpos1 - chXpos2);
    int16_t y_len = abs(chYpos1 - chYpos2);

    if (y_len < x_len) {
        if (chXpos1 > chXpos2) {
            COORDINATE_SWAP(chXpos1, chXpos2, chYpos1, chYpos2);
        }
        int16_t len = x_len;
        int16_t diff = y_len;

        do {
            if (diff >= x_len) {
                diff -= x_len;
                if (chYpos1 < chYpos2) {
                    chYpos1++;
                } else {
                    chYpos1--;
                }
            }

            diff += y_len;
            ssd1306_fill_point(dev, chXpos1++, chYpos1, 1);
        } while (len--);
    }

    else {
        if (chYpos1 > chYpos2) {
            COORDINATE_SWAP(chXpos1, chXpos2, chYpos1, chYpos2);
        }
        int16_t len = y_len;
        int16_t diff = x_len;

        do {
            if (diff >= y_len) {
                diff -= y_len;
                if (chXpos1 < chXpos2) {
                    chXpos1++;
                } else {
                    chXpos1--;
                }
            }

            diff += x_len;
            ssd1306_fill_point(dev, chXpos1, chYpos1++, 1);
        } while (len--);
    }
}

ssd1306_handle_t ssd1306_create(i2c_port_t bus, uint16_t dev_addr)
{
    ssd1306_dev_t *dev = (ssd1306_dev_t *) calloc(1, sizeof(ssd1306_dev_t));
    dev->bus = bus;
    dev->dev_addr = dev_addr << 1;
    ssd1306_init((ssd1306_handle_t) dev);
    return (ssd1306_handle_t) dev;
}

esp_err_t ssd1306_refresh_gram(ssd1306_handle_t dev)
{
    ssd1306_dev_t *device = (ssd1306_dev_t *) dev;
    return ssd1306_write_data(dev, &device->s_chDisplayBuffer[0][0], sizeof(device->s_chDisplayBuffer));
}

